window.PC_DATA = {"course": {"version": 1, "scene": "course", "replay": {"channelId": "8655755", "fileId": "8ea7a282b7f77c8901af3917969db7ca", "title": "Python 入门 · 第 3 讲：列表、字典与循环", "duration": 804, "host": "林老师"}, "rooms": [{"title": "课程导入与容器动机", "start": 0, "end": 72, "summary": "回顾前两讲内容，从50个变量存成绩的痛点引入容器：把同类数据装进列表或字典，再用循环批量处理。", "keywords": ["容器", "列表", "字典", "for循环", "批量处理"], "watched_ratio": 1.0, "fail_rate": 0.06, "items": [{"id": "q01", "keyword": "容器", "question": "用50个变量存成绩的主要问题是什么？", "code": "", "options": ["每个成绩都是孤立的变量，程序没办法批量处理它们", "变量不能存储数字", "列表只能装字符串，不能装数字", "字典只能用来存储成绩"], "explain": "讲师把痛点归结为：每个成绩都是一个孤立的变量，程序没办法批量处理它们；所以要把同类数据装进容器，再用循环依次处理。", "source_time": 58, "source_quote": "程序没办法批量处理它们"}]}, {"title": "列表基础、len、索引与负索引", "start": 73, "end": 213, "summary": "列表用方括号创建，元素用英文逗号隔开，len取元素个数；索引从0开始，负索引从末尾数，越界报IndexError。", "keywords": ["列表", "len", "索引", "负索引", "IndexError"], "watched_ratio": 1.0, "fail_rate": 0.38, "items": [{"id": "q02", "keyword": "列表创建", "question": "创建列表时，正确的写法是？", "code": "scores = [98, 15, 77]", "options": ["用一对方括号，元素之间用英文逗号隔开", "用一对花括号，元素之间用英文逗号隔开", "用一对圆括号，元素之间用英文逗号隔开", "用一对方括号，元素之间用中文逗号隔开"], "explain": "列表用一对方括号创建，元素之间用英文逗号隔开；花括号是后面要讲的字典。", "source_time": 77, "source_quote": "一对方括号里面的元素用英文逗号隔开"}, {"id": "q03", "keyword": "索引", "question": "列表索引的起始值是？", "code": "fruits = ['苹果', '香蕉', '橙子', '葡萄']", "options": ["0", "1", "-1", "列表的长度"], "explain": "索引是从零开始数的，可以把索引理解成离开头有几步：苹果在开头走零步，香蕉要走一步。", "source_time": 120, "source_quote": "索引是从零开始数的"}, {"id": "q04", "keyword": "负索引", "question": "一个四元素列表，合法的负索引范围是？", "code": "", "options": ["-1到-4", "0到3", "-0到-4", "-1到-3"], "explain": "四个元素的列表合法正索引是0到3，负索引是-1到-4；-0就是0。", "source_time": 204, "source_quote": "负索引是-1到-4"}]}, {"title": "切片：包含起点，不包含终点", "start": 214, "end": 256, "summary": "切片写法是方括号里放起点、冒号、终点，包含起点不包含终点；取出的是新列表，不会改动原列表。", "keywords": ["切片", "起点", "终点", "新列表"], "watched_ratio": 1.0, "fail_rate": 0.0, "items": [{"id": "q05", "keyword": "切片", "question": "列表切片a[1:3]会取到哪些下标的元素？", "code": "a = ['苹果', '香蕉', '橙子', '葡萄']\na[1:3]", "options": ["下标1和下标2", "下标1、2、3", "下标0、1、2", "下标1、2、3、4"], "explain": "切片规则是包含起点、不包含终点，所以a[1:3]拿到下标1和2两个元素，下标3的葡萄不包含在内。", "source_time": 224, "source_quote": "不包含终点"}]}, {"title": "列表修改与复制陷阱", "start": 257, "end": 396, "summary": "列表可变；append整体塞入、extend拆开逐个加入、insert按位置插入、remove按值删、pop按位置删并返回值；C=B不是复制而是同一个列表的两个名字。", "keywords": ["append", "extend", "insert", "remove", "pop", "copy", "引用"], "watched_ratio": 1.0, "fail_rate": 0.62, "items": [{"id": "q06", "keyword": "append", "question": "num=[1,2]；执行num.append([3,4])后，num的长度是？", "code": "num = [1, 2]\nnum.append([3, 4])", "options": ["3", "4", "2", "直接报错"], "explain": "append一个列表会把整个列表当成一个元素塞进去，所以长度从2变成3，不是4；想逐个加入要用extend。", "source_time": 287, "source_quote": "它会把整个三四当成一个元素塞进去"}, {"id": "q07", "keyword": "pop", "question": "要从列表里按位置删除并拿到被删的值，用哪个方法？", "code": "", "options": ["pop", "remove", "insert", "append"], "explain": "remove给的是值，按值删除第一个匹配元素；pop给的是位置，默认删最后一个，并且会把删掉的值返回给你。", "source_time": 331, "source_quote": "Pop按位置删"}, {"id": "q08", "keyword": "引用", "question": "执行B=[1,2]；C=B；C.append(3)后，打印B的结果是？", "code": "B = [1, 2]\nC = B\nC.append(3)\nprint(B)", "options": ["[1, 2, 3]", "[1, 2]", "[3]", "报错"], "explain": "C等于B并没有复制一份新列表，B和C只是同一个列表的两个名字，改C就是在改B；真要复制用B.copy或切片B[:]。", "source_time": 369, "source_quote": "因为C等于B并没有复制一份新列表"}]}, {"title": "字典基础、get与键的规则", "start": 397, "end": 550, "summary": "字典用花括号创建，每项写成键:值，按名字取数据；方括号取不到报KeyError，get取不到返回默认值；增改都是d[k]=v，in判断键；键必须不可变。", "keywords": ["字典", "键值对", "KeyError", "get", "in", "不可变"], "watched_ratio": 1.0, "fail_rate": 0.71, "items": [{"id": "q09", "keyword": "字典创建", "question": "字典的每一项应写成什么形式？", "code": "d = {'name': '小明', 'age': 12}", "options": ["键:值", "值:键", "键=值", "键,值"], "explain": "字典用花括号创建，每一项写成键冒号值；取值时用方括号加上键。", "source_time": 405, "source_quote": "每一项写成建冒号值"}, {"id": "q10", "keyword": "KeyError", "question": "用d['score']访问字典中不存在的键，会发生什么？", "code": "d = {'name': '小明', 'age': 12}\nd['score']", "options": ["直接报KeyError，程序停下来", "返回None", "返回0", "自动创建这个键并赋值为None"], "explain": "方括号取不存在的键会直接报KeyError，不会返回None，也不会返回0；想不报错要用get。", "source_time": 435, "source_quote": "错误类型叫key error"}, {"id": "q11", "keyword": "键的不可变", "question": "字典的键必须满足什么规则？", "code": "", "options": ["键必须不可变，字符串、数字、元组可以当键", "键必须是字符串", "键必须是数字", "键可以是列表"], "explain": "规则是键必须是不可变的：字符串、数字、元组都可以当键；列表可变，拿列表当键会报unhashable type list。", "source_time": 521, "source_quote": "规则是剑必须是不可变的"}]}, {"title": "for循环、range、enumerate与遍历字典", "start": 551, "end": 669, "summary": "for循环批量处理；range不含终点；enumerate每轮给下标和元素，下标在前；遍历字典默认拿键，items拿键值对。", "keywords": ["for循环", "range", "enumerate", "items", "values"], "watched_ratio": 1.0, "fail_rate": 0.25, "items": [{"id": "q12", "keyword": "range", "question": "range(3)生成的数字序列是？", "code": "for i in range(3):\n    print(i)", "options": ["0、1、2", "1、2、3", "0、1、2、3", "1、2"], "explain": "range和切片一样不包含终点，range(3)生成0、1、2；想要1、2、3要写range(1,4)。", "source_time": 588, "source_quote": "用range括号三生成的是012"}, {"id": "q13", "keyword": "enumerate", "question": "for i, v in enumerate(fruits)每轮拿到的顺序是？", "code": "fruits = ['苹果', '香蕉', '橙子', '葡萄']\nfor i, v in enumerate(fruits):\n    print(i, v)", "options": ["下标在前，元素在后", "元素在前，下标在后", "只拿到下标", "只拿到元素"], "explain": "enumerate每轮同时给下标和元素，顺序是下标在前、元素在后，写反了结果就全乱。", "source_time": 635, "source_quote": "注意顺序是下标在前"}, {"id": "q14", "keyword": "遍历字典", "question": "直接写for k in d，遍历到的是什么？", "code": "d = {'name': '小明', 'age': 12}\nfor k in d:\n    print(k)", "options": ["键", "值", "键和值组成的元组", "会报错"], "explain": "字典默认遍历的是键；想要值就用items或者values，items每轮拿到键和对应的值。", "source_time": 664, "source_quote": "因为字典默认遍历的事件"}]}, {"title": "综合练习：词频统计与总结", "start": 670, "end": 804, "summary": "词频统计用counts[w]=counts.get(w,0)+1避免KeyError并完成新增与累加；sorted配合lambda按次数从大到小排序；课后作业是统计一篇英文文章，下一讲学函数。", "keywords": ["词频统计", "get默认值", "KeyError", "sorted", "lambda", "items"], "watched_ratio": 1.0, "fail_rate": 0.39, "items": [{"id": "q15", "keyword": "词频统计", "question": "counts[w] = counts.get(w, 0) + 1 的作用是什么？", "code": "counts = {}\nfor w in words:\n    counts[w] = counts.get(w, 0) + 1", "options": ["新词先取默认值0再加1，已有词在原值上加1，避免KeyError", "总是把w的值设为0", "如果w不存在就报KeyError", "把w这个键删掉"], "explain": "第一次遇到某个词，get取到默认值0再加1变成1；再遇到就在原来的基础上加1，一行代码同时解决新增和累加。", "source_time": 717, "source_quote": "get括号W逗号零再加1"}, {"id": "q16", "keyword": "sorted", "question": "sorted(counts.items(), key=lambda kv: kv[1], reverse=True)中，kv[1]表示什么？", "code": "sorted(counts.items(), key=lambda kv: kv[1], reverse=True)", "options": ["值，也就是次数", "键，也就是词", "元素下标", "字典的长度"], "explain": "key参数写kv[1]表示按值，也就是按次数排序；reverse=True表示从大到小，排完之后第一个就是出现最多的词。", "source_time": 742, "source_quote": "key参数写M的KV冒号KV方括号一表示按值"}, {"id": "q17", "keyword": "KeyError", "question": "词频统计里如果直接写counts[w] = counts[w] + 1，第一次遇到新词会发生什么？", "code": "for w in words:\n    counts[w] = counts[w] + 1", "options": ["报KeyError，因为字典里还没有这个键", "返回None并继续执行", "该词计数变成0", "自动新增这个键并计为1"], "explain": "第一次遇到一个新词，字典里还没有这个键，方括号直接取就会报KeyError；解决办法是用get给默认值0。", "source_time": 709, "source_quote": "就会报t error"}]}], "boss_room": 4, "faq": [{"room": 1, "count": 4, "question": "列表索引为什么从0开始？", "answer": "索引是从零开始数的；可以把索引理解成离开头有几步：苹果就在开头走零步，香蕉要走一步，这样记就不会错。", "source_time": 120, "samples": [["阿*", "a[1] 不是苹果吗", "02:10"], ["晚*", "索引为什么从 0 开始啊，有点不习惯", "02:13"], ["夏*", "我一直以为 a[1] 是第一个", "02:13"], ["小*", "从 0 开始？", "02:00"]]}, {"room": 1, "count": 3, "question": "a[-0] 是什么？是最后一个还是第一个？", "answer": "负零就是0，所以取到的是第一个元素（苹果）；并没有负零号座位，也不会报错。", "source_time": 178, "samples": [["土*", "a[-0] 是什么？", "02:43"], ["L*", "a[-0] 会报错吗", "02:56"], ["M*", "老师，a[-0] 为什么不是最后一个？负零和零有区别吗", "02:57"]]}, {"room": 3, "count": 6, "question": "append 和 extend 到底有什么区别？", "answer": "append是整个塞进去，append([3,4])会把[3,4]当成一个元素，长度是3；extend是拆开一个个放，想把3和4逐个加入就用extend，长度变成4。", "source_time": 308, "samples": [["夏*", "append 和 extend 有什么区别", "04:42"], ["阿*", "append 和 extend 老是搞混", "05:04"], ["M*", "append([3,4]) 长度是 3 还是 4", "04:46"], ["西*", "append 能一次加两个吗", "04:36"]]}, {"room": 3, "count": 5, "question": "c = b 不是复制吗？为什么改 c 会改 b？", "answer": "C等于B并没有复制一份新列表，B和C只是同一个列表的两个名字；你改C就是在改B。真的想复制一份，要用B.copy或者切片B[:]。", "source_time": 369, "samples": [["小*", "c = b 不是复制吗", "05:59"], ["老*", "为啥 b 也变了？？", "05:55"], ["K*", "我也以为 b 还是 [1, 2]", "06:02"], ["K*", "c = b 之后改 c 为什么 b 也变了？什么时候需要用 copy？", "06:16"]]}, {"room": 4, "count": 7, "question": "取不存在的键为什么报 KeyError，get 和 [] 怎么选？", "answer": "方括号是必须有没有就报错；get是有就给，没有就给默认值，默认返回None，也可以给第二个参数当默认值。你希望程序报错还是给个默认值，决定了用哪一个。", "source_time": 481, "samples": [["L*", "取不存在的键为什么不返回 None，而是直接报 KeyError？", "07:29"], ["小*", "get 和 [] 有啥区别", "07:38"], ["大*", "get 第二个参数是干嘛的", "07:40"], ["晚*", "什么时候该用 [] 什么时候用 get", "08:01"]]}, {"room": 5, "count": 4, "question": "直接 for k in d 为什么拿不到值？怎么同时拿到键和值？", "answer": "因为字典默认遍历的是键；想要值就用items或者values，d.items()每轮拿到键和对应的值，最常用。", "source_time": 667, "samples": [["Z*", "直接 for k in d 拿不到值吗", "10:45"], ["晚*", "遍历字典时怎么同时拿到键和值？", "11:00"], ["M*", "items 和 values 有什么区别", "10:51"], ["晚*", "for k in d 为什么只有键", "10:57"]]}, {"room": 5, "count": 4, "question": "range(3)为什么是0 1 2，不包含3？", "answer": "range和切片一样不包含终点，range(3)生成0、1、2，一共三个数；想从1开始就写range(1,4)生成1、2、3。", "source_time": 588, "samples": [["阿*", "range(3) 是 0 1 2 还是 1 2 3", "09:47"], ["北*", "range 包含 3 吗", "09:51"], ["北*", "range(3) 为什么不包含 3？", "09:59"], ["奶*", "为啥打印的是 0 1 2", "10:01"]]}, {"room": 6, "count": 4, "question": "sorted 里的 lambda kv: kv[1] 是什么意思？", "answer": "key参数写kv[1]表示按值，也就是按次数排序；reverse=True表示从大到小，排完之后第一个就是出现最多的词。lambda后面会专门讲，今天先会用就行。", "source_time": 742, "samples": [["程*", "lambda 是什么", "12:16"], ["夏*", "kv[1] 是次数对吧", "12:23"], ["程*", "sorted 里的 lambda kv: kv[1] 是什么意思？", "12:33"], ["七*", "lambda 下节课讲吗", "12:39"]]}], "pairs": [{"a": "append", "b": "extend", "diff": "append是整个塞进去，append一个列表会整体作为一个元素塞入，长度只加1；extend是拆开一个个放，会把参数拆开逐个加入。", "source_time": 308}, {"a": "remove", "b": "pop", "diff": "remove给的是值，按值删掉第一个匹配元素；pop给的是位置，默认删最后一个，并且会把删掉的那个值返回给你。", "source_time": 343}, {"a": "d[key]", "b": "d.get(key)", "diff": "方括号是必须有没有就报错（KeyError）；get是有就给，没有就给默认值，默认None，也可指定默认值。", "source_time": 481}, {"a": "列表", "b": "元组", "diff": "列表用方括号、可以修改，所以不能当字典的键；元组用圆括号、不能修改，所以元组可以当键。", "source_time": 543}, {"a": "d.values()", "b": "d.items()", "diff": "values只拿值；items每轮拿到一个键和对应的值，最常用。", "source_time": 651}], "handout": {"title": "Python入门第3讲 直播讲义", "markdown": "# Python入门第3讲 直播讲义\n\n## 1. 课程导入与容器动机（00:00–01:12）\n- 回顾前两讲：变量、数据类型、if条件判断。\n- 本讲学三样东西：列表、字典、for循环，目标是写出词频统计小程序。\n- 痛点：用50个变量存成绩、逐个相加算平均分很麻烦，转来新同学还得改代码；问题是每个成绩都是孤立变量，程序没办法批量处理。\n- 解法：把同类数据装进容器，再用循环依次处理。\n\n## 2. 列表基础、len、索引与负索引（01:13–03:33）\n- 列表用一对方括号创建，元素之间用英文逗号隔开；空方括号是空列表；可装数字也可装字符串。\n- len(列表)取元素个数；注意列表用方括号，花括号是后面要讲的字典。\n- 索引从0开始，可理解成“离开头有几步”；四元素列表合法正索引0到3。\n- 负索引从末尾往回数：-1是最后一个，-2是倒数第二个，等价于len-1；-0就是0，取到第一个元素。\n- 越界会报IndexError: list index out of range；四元素列表合法负索引-1到-4。\n\n## 3. 切片：包含起点，不包含终点（03:34–04:16）\n- 写法：[起点:终点]；规则：包含起点，不包含终点。\n- a[1:3]拿到下标1和2；起点省略表示从头开始，终点省略表示取到末尾。\n- 切片取出的是新列表，不会改动原列表；这条规则讲range时还会再用到。\n\n## 4. 列表修改与复制陷阱（04:17–06:36）\n- 列表可变。append每次在末尾加一个元素，append一个列表会整体塞入，长度只加1。\n- extend把参数拆开逐个加入；insert第一个参数是位置，第二个是值。\n- remove按值删除第一个匹配元素；pop按位置删除，默认删最后一个，并把删掉的值返回。\n- 大坑：C=B不是复制，B和C是同一个列表的两个名字，改C就是改B；要复制用B.copy或切片B[:]。\n\n## 5. 字典基础、get与键的规则（06:37–09:10）\n- 字典用花括号创建，每项写成键:值；列表按位置找数据，字典按名字找数据。\n- d[key]取不存在的键会直接报KeyError，不返回None也不返回0；线上常见于用户没填字段。\n- d.get(key)取不到默认返回None，第二个参数可指定默认值；键存在时默认值不起作用。\n- 一句话区分：方括号是必须有没有就报错，get是有就给、没有就给默认值。\n- 新增和修改都是d[key]=value；删除用del或pop；in判断的是键不是值。\n- 键必须不可变：字符串、数字、元组可当键；列表可变，当键会报unhashable type list。\n\n## 6. for循环、range、enumerate与遍历字典（09:11–11:09）\n- for变量in列表：冒号下缩进是循环体，每轮取出一个元素；算平均分四行就解决，加同学也不用改代码。\n- range(3)生成0、1、2，不含终点3；range(1,4)生成1、2、3。\n- enumerate每轮给下标和元素，顺序是下标在前、元素在后，写反结果就全乱。\n- 遍历字典三种方式：直接for k in d拿到的是键；d.values()只拿值；d.items()每轮拿键和对应的值，最常用。\n\n## 7. 综合练习：词频统计与总结（11:10–13:24）\n- 思路：用字典记数，遍历每个词，新词记1，已有词在原次数上加1。\n- 直接写counts[w]=counts[w]+1，第一次遇到新词会报KeyError。\n- 正解：counts[w] = counts.get(w, 0) + 1，一行同时完成新增和累加。\n- 排序：sorted(counts.items(), key=lambda kv: kv[1], reverse=True)，kv[1]表示按值（次数），reverse=True从大到小，第一个就是出现最多的词；lambda今天先会用就行。\n- 回顾：索引从0开始、负索引从末尾数、切片包含起点不包含终点；append整体塞入、extend拆开加入、C=B不是复制；方括号取不到报KeyError、get可给默认值、键必须不可变；for配合range、enumerate和items。\n- 课后作业：把词频统计改成统计一篇英文文章；下一讲学习函数。"}, "skin": "dungeon", "traces": {"0": {"question": "为什么用50个变量存成绩的做法需要改成列表/字典容器？", "total": 18, "wrong": 1, "samples": [["阿杰", "变量不能存储数字"]]}, "1": {"question": "对于四元素列表 fruits = ['苹果','香蕉','橙子','葡萄']，下列哪个索引访问会引发 IndexError？", "total": 21, "wrong": 6, "samples": [["小周", "fruits[-4]"], ["阿飞", "fruits[-4]"], ["糖糖", "fruits[-4]"], ["夏夏", "fruits[3]"]]}, "3": {"question": "关于 remove 和 pop，下列说法正确的是？", "total": 21, "wrong": 13, "samples": [["北辰", "remove 按位置删除，pop 按值删除"], ["晚风", "pop 按值删除且没有返回值"], ["奶茶三分糖", "remove 删除所有匹配元素并返回列表"], ["夏夏", "pop 按值删除且没有返回值"]]}, "5": {"question": "range(1, 5) 生成的数字序列是什么？", "total": 23, "wrong": 8, "samples": [["程序媛小鹿", "0, 1, 2, 3, 4"], ["阿杰", "0, 1, 2, 3, 4"], ["秋秋", "1, 2, 3, 4, 5"], ["小满", "1, 2, 3, 4, 5"]]}, "6": {"question": "sorted(counts.items(), key=lambda kv: kv[1], reverse=True) 的作用是什么？", "total": 18, "wrong": 7, "samples": [["北辰", "按值从大到小排序后第一个是字典的键"], ["七七", "按值从小到大排序"], ["老王学Python", "按值从大到小排序后第一个是字典的键"], ["阿飞", "按键从大到小排序"]]}, "4": {"question": "下列哪种类型不能作为字典的键？", "total": 21, "wrong": 15, "samples": [["阿杰", "元组"], ["Kevin", "字符串"], ["Leo", "字符串"], ["小树", "字符串"]]}}, "video": "media/course.mp4"}, "commerce": {"title": "不夜城集市 · 秋冬好物专场", "host": "阿月", "video": "media/commerce.mp4", "products": [{"key": "cup", "name": "宋锦纹保温杯 500ml", "price": 129, "originalPrice": 169, "cover": "https://liveimages.videocc.net/uploaded/images/2026/10/hng5vgjxot.png", "desc": "316 不锈钢内胆，500ml；黛青、朱砂、月白三色；杯身直径 7.2cm，可放进多数车载杯架；另有 350ml 款（89 元）", "detail": "容量 500ml（另有 350ml 款，89 元，两款杯盖通用）；内胆 316 不锈钢，外壳 304 不锈钢；杯身直径 7.2cm、高 24cm、重 360g；保温测试：装 95℃ 热水，室温 20℃ 静置 12 小时后约 62℃（实验室数据，实际随环境变化）；杯盖含硅胶密封圈，可单独购买替换装；不建议装碳酸饮料和牛奶久放。", "start": 58.8, "end": 157.5, "quotes": ["第一样，宋锦纹保温杯。", "杯身的纹样取自宋代的锦缎图案，有黛青、朱砂、月白三个颜色。", "内胆是 316 不锈钢，外壳是 304 不锈钢。", "容量五百毫升，日常价一百六十九元，今晚直播间一百二十九元。", "很多家人会问 316 和 304 有什么区别，简单说，316 在 304 的基础上加了钼，耐腐蚀性更好一些，所以我们把它用在直接接触饮品的内胆上。", "保温效果我们说实测数据，不说空话：装九十五度的热水，室温二十度静置十二小时，打开大约还有六十二度。"]}, {"key": "scarf", "name": "羊毛混纺围巾", "price": 159, "originalPrice": 199, "cover": "https://liveimages.videocc.net/uploaded/images/2026/10/hng5vkyafv.png", "desc": "70% 羊毛 + 30% 锦纶，180×30cm；烟灰、驼色、酒红三色；手洗或干洗", "detail": "成分 70% 羊毛、30% 锦纶，不是纯羊绒；尺寸 180×30cm（含流苏），重约 160g；洗涤：30℃ 以下冷水手洗或干洗，不可机洗、不可烘干，平铺阴干；初次佩戴可能有少量浮毛，属正常现象；七天无理由退换需吊牌未拆。", "start": 157.5, "end": 246.2, "quotes": ["第二样，羊毛混纺围巾。", "先说清楚成分：百分之七十羊毛，百分之三十锦纶，它不是纯羊绒，我们不会把它说成羊绒围巾。", "加锦纶是为了更耐磨、不容易变形。", "尺寸是一百八十乘三十厘米，含流苏，重量大约一百六十克，可以绕脖子两圈。", "颜色有烟灰、驼色、酒红。", "日常价一百九十九元，直播间一百五十九元。"]}, {"key": "mask", "name": "桑蚕丝遮光眼罩", "price": 69, "originalPrice": 89, "cover": "https://liveimages.videocc.net/uploaded/images/2026/10/hng5vnlk98.png", "desc": "22 姆米桑蚕丝面料，弹力绑带可调节；单只 69 元，两件装 118 元", "detail": "面料 22 姆米桑蚕丝，内填充为聚酯纤维，并非整只都是真丝；绑带为弹力松紧带，周长约 52–62cm 可调；遮光为物理遮挡，不具备治疗作用；手洗，水温不超过 30℃，勿暴晒；单只 69 元，两件装 118 元（两件装为同色）。", "start": 246.2, "end": 305.0, "quotes": ["第三样，桑蚕丝遮光眼罩。", "面料是二十二姆米的桑蚕丝，姆米是真丝的重量单位，数字越大，丝越厚实。", "这里也说实话：贴脸的面料是真丝，里面的填充是聚酯纤维，并不是整只都是真丝。", "单只六十九元，两件装一百一十八元，两件装是同一个颜色，想要两个颜色请分开拍。", "眼罩能做的事情很简单，就是物理遮光，适合午休、坐高铁、出差住酒店的时候用。", "绑带是弹力松紧带，周长大约五十二到六十二厘米，可以调节，头围比较大的家人一般也能戴。"]}, {"key": "coffee", "name": "云南保山挂耳咖啡", "price": 89, "originalPrice": 109, "cover": "https://liveimages.videocc.net/uploaded/images/2026/10/hng5vq9a97.png", "desc": "云南保山小粒咖啡，中度烘焙，10g×20 包；保质期 12 个月", "detail": "产地云南保山，阿拉比卡种；中度烘焙，风味描述为坚果、可可、微酸；每包 10g，一盒 20 包；建议 92℃ 左右热水分三次注入，总水量约 180ml；保质期 12 个月，开封后尽快饮用；含咖啡因，孕妇及对咖啡因敏感人群请谨慎饮用。", "start": 305.0, "end": 360.2, "quotes": ["第四样，挂耳咖啡。", "豆子来自云南保山，是阿拉比卡种的小粒咖啡，中度烘焙，喝起来有坚果和可可的味道，带一点点酸。", "每包十克，一盒二十包，日常价一百零九元，直播间八十九元，算下来一包四块多。", "不喜欢酸味的家人可以放心，中度烘焙的酸感比较轻。", "挂耳怎么冲？", "把挂耳挂在杯口，用九十二度左右的热水，不要用刚烧开的沸水，分三次慢慢注入，第一次少一点，让粉闷二十秒左右，总水量大约一百八十毫升。"]}], "faq": [{"room": 0, "count": 3, "question": "到手价还能再用券吗？满199减30能不能跨商品凑单？", "answer": "直播间标价就是到手价，不需要再领券；满199元减30元可以跨商品凑单，比如保温杯129元加眼罩69元就够了。优惠到今晚直播结束前有效。", "source_time": 29, "samples": [["精*", "到手价是不是还能用券", "00:30"], ["理*", "满 199 减 30 能跨商品凑吗", "00:36"], ["凑*", "保温杯加眼罩够 199 吗", "00:45"]]}, {"room": 0, "count": 1, "question": "新疆、西藏这些地方包邮吗？", "answer": "全场包邮，新疆、西藏这些偏远地区除外。", "source_time": 43, "samples": [["新*", "新疆包邮吗", "00:42"]]}, {"room": 1, "count": 3, "question": "316和304不锈钢有什么区别？内胆外壳分别是什么？", "answer": "316在304的基础上耐腐蚀性更好一些，所以用在直接接触饮品的内胆上；这款杯子内胆是316不锈钢，外壳是304不锈钢。", "source_time": 88, "samples": [["成*", "316 和 304 有什么区别", "01:10"], ["小*", "316 是不是更好", "01:13"], ["头*", "内胆是 316 外壳是 304？", "01:17"]]}, {"room": 1, "count": 3, "question": "杯子能保温多久？冬天放车里还行吗？", "answer": "实测装95度热水、室温20度静置12小时，打开大约还有62度；这是实验室数据，冬天放在室外会低一些。", "source_time": 102, "samples": [["杯*", "能保温多久", "01:38"], ["出*", "冬天放车里还能保温吗", "01:41"], ["精*", "12 小时还有 62 度，可以", "01:43"]]}, {"room": 1, "count": 3, "question": "350毫升和500毫升怎么选？杯盖通用吗？", "answer": "500毫升129元，一天在办公室喝水、开车通勤选500；350毫升89元，更短更轻，只是出门带一杯选350。两款的杯盖密封圈是通用的，也可以单独买替换装。", "source_time": 145, "samples": [["理*", "350 和 500 有什么区别", "02:09"], ["凑*", "350ml 的多少钱", "02:13"], ["上*", "日常上班通勤，500ml 和 350ml 哪个更合适？", "02:24"]]}, {"room": 2, "count": 4, "question": "围巾是羊绒的吗？羊毛混纺和纯羊绒差在哪？", "answer": "成分是70%羊毛、30%锦纶，不是纯羊绒。羊绒更细更软也更轻，同尺寸的纯羊绒围巾价格通常要高好几倍；这条手感没有那么细腻，但更耐磨、不容易变形。", "source_time": 165, "samples": [["两*", "是羊绒的吗", "02:40"], ["成*", "混纺是不是不保暖", "03:16"], ["围*", "羊毛混纺围巾和纯羊绒围巾有什么区别？", "03:18"]]}, {"room": 2, "count": 3, "question": "围巾能机洗吗？能用烘干机吗？洗完怎么晾？", "answer": "用30度以下的冷水手洗或者直接干洗，不可以机洗、也不可以烘干；洗完平铺阴干，不要挂着晾，否则会被拉长变形。", "source_time": 226, "samples": [["精*", "能机洗吗", "03:43"], ["怕*", "可以放洗衣机吗", "03:47"], ["理*", "能用烘干机吗", "03:50"]]}, {"room": 3, "count": 3, "question": "眼罩是真丝的吗？整只都是真丝吗？22姆米是什么意思？", "answer": "贴脸的面料是22姆米桑蚕丝，里面的填充是聚酯纤维，并不是整只都是真丝；姆米是真丝的重量单位，数字越大丝越厚实。", "source_time": 262, "samples": [["新*", "是真丝的吗", "04:09"], ["黑*", "整只都是真丝吗", "04:13"], ["宝*", "22 姆米是什么意思", "04:16"]]}, {"room": 3, "count": 3, "question": "眼罩能助眠吗？戴着能治失眠吗？", "answer": "眼罩能做的事很简单，就是物理遮光，不具备任何治疗作用；如果是长期失眠，请一定去看医生。", "source_time": 290, "samples": [["小*", "能助眠吗", "04:36"], ["成*", "戴着能治失眠吗", "04:40"], ["成*", "这款眼罩能帮助改善失眠吗？", "04:42"]]}, {"room": 4, "count": 3, "question": "挂耳咖啡能用刚烧开的水冲吗？水温多少合适？", "answer": "把挂耳挂在杯口，用约92度的热水，不要用刚烧开的沸水；分三次慢慢注入，第一次少一点让粉焖20秒左右，总水量大约180毫升。", "source_time": 336, "samples": [["理*", "用开水冲可以吗", "05:34"], ["理*", "挂耳咖啡可以直接用刚烧开的水冲吗？", "05:36"], ["售*", "水温多少", "05:38"]]}, {"room": 5, "count": 2, "question": "咖啡拆封了还能退吗？", "answer": "咖啡属于食品，拆封之后不支持无理由退换；未拆封的按全场七天无理由执行，每单还赠送运费险。", "source_time": 370, "samples": [["宝*", "咖啡拆了能退吗", "06:03"], ["宝*", "挂耳咖啡拆封以后还能退吗？", "06:05"]]}, {"room": 5, "count": 2, "question": "有运费险吗？退货运费谁出？", "answer": "每一单都赠送运费险，退回来的运费不用顾客出。", "source_time": 375, "samples": [["两*", "有运费险吗", "06:07"], ["急*", "退货运费谁出", "06:11"]]}], "rooms": [{"title": "开场与优惠规则", "start": 0, "end": 58}, {"title": "宋锦纹保温杯", "start": 58, "end": 157}, {"title": "羊毛混纺围巾", "start": 157, "end": 246}, {"title": "桑蚕丝遮光眼罩", "start": 246, "end": 305}, {"title": "云南挂耳咖啡", "start": 305, "end": 360}, {"title": "统一售后与价格返场", "start": 360, "end": 428}]}, "series": [{"no": 1, "title": "变量与类型", "views": 2380, "state": "cleared"}, {"no": 2, "title": "条件与循环", "views": 2105, "state": "cleared"}, {"no": 3, "title": "列表、字典与循环", "views": 1862, "state": "open"}, {"no": 4, "title": "函数与模块", "views": 0, "state": "locked"}], "screen": "data:image/jpeg;base64,"};
